-- Cross-device user data. client_id is generated by the iOS client and is
-- unique per user so retries are idempotent.

CREATE TABLE food_logs (
    id VARCHAR(36) NOT NULL,
    user_id VARCHAR(36) NOT NULL,
    client_id VARCHAR(36) NOT NULL,
    logged_at DATETIME NOT NULL,
    meal VARCHAR(20) NOT NULL,
    food_name VARCHAR(120) NOT NULL,
    grams FLOAT NOT NULL,
    kcal FLOAT NOT NULL,
    protein FLOAT NOT NULL,
    carbs FLOAT NOT NULL,
    fat FLOAT NOT NULL,
    fiber FLOAT NOT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_food_logs_user_client UNIQUE (user_id, client_id),
    FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE,
    INDEX ix_food_logs_user_logged (user_id, logged_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE body_metrics (
    id VARCHAR(36) NOT NULL,
    user_id VARCHAR(36) NOT NULL,
    client_id VARCHAR(36) NOT NULL,
    measured_at DATETIME NOT NULL,
    weight_kg FLOAT NOT NULL,
    body_fat_pct FLOAT NOT NULL,
    waist_cm FLOAT NOT NULL,
    arm_cm FLOAT,
    thigh_cm FLOAT,
    created_at DATETIME NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_body_metrics_user_client UNIQUE (user_id, client_id),
    FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE,
    INDEX ix_body_metrics_user_measured (user_id, measured_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE equipment_library (
    id VARCHAR(36) NOT NULL,
    user_id VARCHAR(36) NOT NULL,
    client_id VARCHAR(36) NOT NULL,
    name VARCHAR(120) NOT NULL,
    slug VARCHAR(80),
    muscle VARCHAR(30),
    equipment VARCHAR(30),
    notes TEXT NOT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_equipment_library_user_client UNIQUE (user_id, client_id),
    FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE,
    INDEX ix_equipment_library_user_created (user_id, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
